"""Normalize a published whole-tree owner offer; creates native metadata only."""
import argparse,pathlib,json,base64,hashlib
import manage,result_outbox
P=pathlib.Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--project',choices=['EP_L2','DTC_L1'],required=True);p.add_argument('--experiment',required=True);p.add_argument('--owner-ready',type=P);p.add_argument('--owner-commit',required=True);p.add_argument('--owner-path',required=True);p.add_argument('--owner-auxiliary-dir',type=P);p.add_argument('--output',type=P,required=True);a=p.parse_args();manage.target_identity();manage.require(a.output.is_absolute() and a.output.resolve().is_relative_to(manage.ROOT/'outbox') and not a.output.exists(),'fresh metadata output under native outbox required')
 pub=manage.rpc({'action':'owner_publication','project':a.project,'commit':a.owner_commit,'path':a.owner_path,'include_bytes':a.owner_ready is None});raw=a.owner_ready.read_bytes() if a.owner_ready else base64.b64decode(pub['data']['raw_base64']);ready=json.loads(raw);source=ready.get('complete_tree_path',ready.get('source_root'));manage.require(pub['data']['sha256']==hashlib.sha256(raw).hexdigest(),'owner publication bytes not matched');record=manage.rpc({'action':'experiment','project':a.project,'experiment':a.experiment});state=manage.status(a.project);gate=manage.fence('result.archive',state);manage.require(gate['allowed'],'management epoch not current');manage.require(record['data']['source_root']==source,'owner/current result root mismatch')
 aux={}
 if 'full_file_records' in ready:
  for desc in ready['full_file_records']+[ready[k] for k in ['directory_records','link_records']]:
   name=P(desc['path']);manage.require(not name.is_absolute() and '..' not in name.parts,'unsafe owner auxiliary path');aux[desc['path']]=base64.b64encode((a.owner_auxiliary_dir/name).read_bytes()).decode() if a.owner_auxiliary_dir else manage.rpc({'action':'owner_publication','project':a.project,'commit':a.owner_commit,'path':str(P(a.owner_path).parent/name),'include_bytes':True})['data']['raw_base64']
 shell={'owner_auxiliary_base64':aux};rows=result_outbox.owner_entries(ready,shell,P(source));head=record['Source_identity'];root=next(r for r in rows if r['path']=='.');slug=a.project+'_'+P(source).name;closed=(ready.get('all_known_owner_writers_closed') is True or ready.get('write_closure',{}).get('status')=='FINALIZED_AND_NO_SELECTED_WRITER_OBSERVED');reader=ready.get('reader_disposition');manage.require(closed and reader,'owner closure/readers not qualified')
 m={'schema':'FULL_RESULT_TYPED_BUNDLE_MANIFEST_V1','project':slug,'source_root':source,'source_filesystem_identity':{'host':head['host'],'boot_id':head['boot_id'],'mount_namespace':head['namespace'],'dev':root['dev'],'root_inode':root['inode']},'source_frozen_commit':a.owner_commit,'owner_ready_sha256':hashlib.sha256(raw).hexdigest(),'full_owner_ready_verified':True,'source_disposition':'SOURCE_KEEP','hardlink_policy':'COPY_BYTES_EXTERNAL_ALIAS_PROVENANCE' if any(r['type']=='file' and r['nlink']>1 for r in rows) else 'REFUSE','genuine164_destination_root':str(P(result_outbox.BASE)/slug).replace('/root/share/mnt164','/home/shared',1),'entries':rows,'reused_objects':{},'selector_sha256':result_outbox.sha(result_outbox.canonical(rows))}
 m['txid']=result_outbox.sha(result_outbox.canonical({k:m[k] for k in ['source_filesystem_identity','source_root','selector_sha256','source_frozen_commit','genuine164_destination_root']}));leases=state['data'].get('active_resource_leases',{});reserved=sum(max(x.get('disk_growth_bytes',0),x.get('result_growth_bytes',0)) for x in leases.values())
 offer={'schema':'CURRENT_OWNER_FROZEN_RESULT_OUTBOX_OFFER_V1','project':a.project,'experiment':a.experiment,'manifest':m,'owner_ready_base64':base64.b64encode(raw).decode(),'owner_auxiliary_base64':aux,'source_disposition':'SOURCE_KEEP','owner_qualification_publication':a.owner_commit,'owner_ready_publication_path':a.owner_path,'owner_membership_manifest_sha256':m['selector_sha256'],'all_owner_file_hashes_stat_directories_links_crosschecked':True,'owner_writer_closed':closed,'owner_reader_disposition':reader,'scientific_acceptance_reference':record['data']['owner_accepted_reference'],'current_all_project_write_reservation_bytes':reserved}
 result_outbox.bind(offer,manage.CATALOG,record);a.output.parent.mkdir(parents=True,exist_ok=True)
 with a.output.open('xb') as f:f.write((json.dumps(offer,indent=2)+'\n').encode())
 print(json.dumps({'state':'NATIVE_OUTBOX_METADATA_PREPARED_NO_PAYLOAD','path':str(a.output),'txid':m['txid'],'Source_disposition':'SOURCE_KEEP','science_starts':0}))
if __name__=='__main__':main()
